-- bill2_admin_call_report(timestamp with time zone,timestamp with time zone,integer)
CREATE OR REPLACE FUNCTION public.bill2_admin_call_report(p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer)
 RETURNS TABLE(call_id uuid, run_id uuid, call_sequence integer, created_at timestamp with time zone, provider text, model text, call_state text, selected_cost_usd text, run_state text, run_outcome text, credits_per_usd text, run_multiplier text, run_charged integer, run_actual_restore integer, run_call_count integer, call_multiplier text, multiplier_source text, purpose text, contract_version text, settled_at timestamp with time zone, nominal_cost_usd text, nominal_source text, charged_delta integer, theoretical_delta text, platform_absorbed_cap_credits text, platform_absorbed_bound_credits text, platform_absorbed_cap_usd text, platform_absorbed_bound_usd text, platform_margin_usd text, platform_margin_cache_read_usd text, platform_margin_cache_write_usd text, platform_margin_other_usd text, compensation_credits integer, compensated_at timestamp with time zone, call_kind text, supplier_cost_state text, supplier_cost_bound_usd text)
